/// @title FP127 Primitives
/// @notice Low-level macros for safe comparisons, negation, and bit operations
/// @dev These macros encode the correct EVM operand order to prevent bugs.
///      EVM comparison/subtraction operand order:
///        - SUB pops [a, b] and pushes (a - b), so "a on top" means a - b
///        - LT/GT/SLT/SGT pop [a, b] and push (a < b) or (a > b)
///      Common pattern: to check "x < THRESHOLD", use: THRESHOLD swap1 lt
///      This file provides named macros for the most error-prone patterns.
/// @dev Requires: constants.huff must be included before this file

// ============================================================================
// Sign and Negation
// ============================================================================

/// @notice Check if top-of-stack is negative (signed comparison)
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [x < 0] (1 if negative, 0 otherwise)
#define macro IS_NEGATIVE() = takes(1) returns(1) {
    0x00 swap1 slt    // [x < 0]
}

/// @notice Negate top-of-stack (two's complement)
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [-x]
/// SUB pops [a, b] and pushes (a - b), so we need [0, x] on stack for 0 - x
#define macro NEGATE() = takes(1) returns(1) {
    0x00 sub          // [0 - x = -x]
}

// ============================================================================
// Arithmetic Helper Functions
// ============================================================================

/// @notice Newton-Raphson sqrt step: y = (y + x/y) / 2
/// @dev takes(2) returns(2)
/// Stack input:  [y, x]
/// Stack output: [y_new, x]
/// Requires FP127_DIV_UNSIGNED to be defined (sqrt always operates on positive values)
/// @dev Converted to function to save ~93 bytes (7 call sites)
#define fn NEWTON_SQRT_STEP() = takes(2) returns(2) {
    dup1 dup3 swap1            // [y, x, y, x]
    FP127_DIV_UNSIGNED()       // [x/y, y, x]
    add 0x01 shr               // [y_new, x]
}

// ============================================================================
// Most Significant Bit (MSB) Binary Search
// ============================================================================

/// @notice Find the position of the most significant bit using binary search
/// @dev takes(1) returns(1)
/// Stack input:  [x] (any uint256 > 0)
/// Stack output: [msb] (bit position, 0-255)
/// Algorithm: Binary search checking 128, 64, 32, 16, 8, 4, 2, 1 bit ranges
/// Gas: ~150 (8 conditional jumps)
///
/// Comparison pattern used throughout: "THRESHOLD swap1 lt" = "x < THRESHOLD"
/// If x >= THRESHOLD, we don't jump, we add bits and shift.
#define fn MSB() = takes(1) returns(1) {
    // Binary search for MSB
    // Stack: [x]
    0x00                       // [msb=0, x]

    // Check if x >= 2^128 (jump if x < 2^128)
    dup2 0x100000000000000000000000000000000 swap1 lt msb_skip_128 jumpi
    0x80 add swap1 0x80 shr swap1
    msb_skip_128:

    // Check if y >= 2^64
    dup2 0x10000000000000000 swap1 lt msb_skip_64 jumpi
    0x40 add swap1 0x40 shr swap1
    msb_skip_64:

    // Check if y >= 2^32
    dup2 0x100000000 swap1 lt msb_skip_32 jumpi
    0x20 add swap1 0x20 shr swap1
    msb_skip_32:

    // Check if y >= 2^16
    dup2 0x10000 swap1 lt msb_skip_16 jumpi
    0x10 add swap1 0x10 shr swap1
    msb_skip_16:

    // Check if y >= 2^8
    dup2 0x100 swap1 lt msb_skip_8 jumpi
    0x08 add swap1 0x08 shr swap1
    msb_skip_8:

    // Check if y >= 2^4
    dup2 0x10 swap1 lt msb_skip_4 jumpi
    0x04 add swap1 0x04 shr swap1
    msb_skip_4:

    // Check if y >= 2^2
    dup2 0x04 swap1 lt msb_skip_2 jumpi
    0x02 add swap1 0x02 shr swap1
    msb_skip_2:

    // Check if y >= 2^1
    dup2 0x02 swap1 lt msb_skip_1 jumpi
    0x01 add swap1 0x01 shr swap1
    msb_skip_1:

    // Stack: [msb, y (should be 1)]
    swap1 pop                  // [msb]
}

/// @title FP127 - 127.128 Fixed-Point Arithmetic Library
/// @notice Signed fixed-point operations using two's complement
/// @dev Format: 128 integer bits + 128 fractional bits
///      All operations preserve sign via two's complement
/// @dev Requires: constants.huff must be included before this file

/// @notice Add two 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input: [a, b]
/// Stack output: [a + b]
#define macro FP127_ADD() = takes(2) returns(1) {
    add
}

/// @notice Subtract two 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input: [a, b] (b on top)
/// Stack output: [a - b]
#define fn FP127_SUB() = takes(2) returns(1) {
    swap1     // [a, b] -> [b, a]
    sub       // b - a
}

/// @notice Convert signed fixed18 to 127.128 format
/// @dev takes(1) returns(1)
/// Stack input: [fixed18_value] (signed int256 representing value * 1e18)
/// Stack output: [fp127_value] (signed int256 representing value * 2^128)
/// Formula: fp127 = (fixed18 * 2^128) / 1e18
/// Gas: ~100 (optimized)
#define fn FP127_FROM_FIXED18() = takes(1) returns(1) {
    // Input: [fixed18]
    // We need: (fixed18 * 2^128) / 1e18
    // For typical calculator use (values up to ~10^20), we're safe:
    // 10^20 * 2^128 ≈ 2^195, well within 256 bits.

    0x80 shl              // [fixed18 << 128] (PUSH1 + SHL = 6 gas)
    [FIXED18_SCALE]       // [1e18, fixed18 << 128]
    swap1 sdiv            // [result] (SDIV pops dividend then divisor)
}

/// @notice Convert 127.128 format to signed fixed18
/// @dev takes(1) returns(1)
/// Stack input: [fp127_value] (signed int256 representing value * 2^128)
/// Stack output: [fixed18_value] (signed int256 representing value * 1e18)
/// Formula: fixed18 = (fp127_hi * 1e18) + ((fp127_lo * 1e18) >> 128)
///          Split to avoid overflow: fp127 * 1e18 can exceed 256 bits
/// Gas: ~120 (prevents overflow for all valid fp127 values)
#define fn FP127_TO_FIXED18() = takes(1) returns(1) {
    // Input: [fp127]
    // Split: fp127 = (fp127_hi << 128) + fp127_lo
    // Result: (fp127_hi * 1e18) + ((fp127_lo * 1e18) >> 128)

    dup1                      // [fp127, fp127]
    0x80 sar                  // [fp127_hi, fp127]
    [FIXED18_SCALE]           // [1e18, fp127_hi, fp127]
    mul                       // [fp127_hi * 1e18, fp127]

    swap1                     // [fp127, fp127_hi * 1e18]
    [MASK128] and             // [fp127_lo, fp127_hi * 1e18]
    [FIXED18_SCALE]           // [1e18, fp127_lo, fp127_hi * 1e18]
    mul                       // [fp127_lo * 1e18, fp127_hi * 1e18]
    0x80 shr                  // [(fp127_lo * 1e18) >> 128, fp127_hi * 1e18]

    add                       // [result]
}

/// @notice Multiply two 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input: [b, a] (b on top)
/// Stack output: [a * b]
/// Formula: result = (a * b) / 2^128
///          Optimized: push MASK128 once and reuse via dup
/// Gas: ~110-130 (reduced PUSH32 operations)
#define fn FP127_MUL() = takes(2) returns(1) {
    // Input: [b, a]
    // Split both: a = a_hi * 2^128 + a_lo, b = b_hi * 2^128 + b_lo
    // Result = a_hi * b_hi * 2^128 + a_hi * b_lo + a_lo * b_hi + (a_lo * b_lo) >> 128

    // Push MASK128 once for reuse
    [MASK128]             // [MASK, b, a]

    // Term1: (a_hi * b_hi) << 128
    // Stack: [MASK, b, a]
    dup3 0x80 sar         // [a_hi, MASK, b, a]
    dup3 0x80 sar         // [b_hi, a_hi, MASK, b, a]
    mul                   // [a_hi*b_hi, MASK, b, a]
    0x80 shl              // [term1, MASK, b, a]

    // Term2: a_hi * b_lo
    // Stack: [term1, MASK, b, a]
    dup4 0x80 sar         // [a_hi, term1, MASK, b, a]
    dup4 dup4 and         // [b_lo, a_hi, term1, MASK, b, a]
    mul                   // [a_hi*b_lo, term1, MASK, b, a]
    add                   // [sum12, MASK, b, a]

    // Term3: a_lo * b_hi
    // Stack: [sum12, MASK, b, a]
    dup4 dup3 and         // [a_lo, sum12, MASK, b, a]
    dup4 0x80 sar         // [b_hi, a_lo, sum12, MASK, b, a]
    mul                   // [a_lo*b_hi, sum12, MASK, b, a]
    add                   // [sum123, MASK, b, a]

    // Term4: (a_lo * b_lo) >> 128
    // Stack: [sum123, MASK, b, a]
    dup4 dup3 and         // [a_lo, sum123, MASK, b, a]
    dup4 dup4 and         // [b_lo, a_lo, sum123, MASK, b, a]
    mul                   // [a_lo*b_lo, sum123, MASK, b, a]
    0x80 shr              // [(a_lo*b_lo)>>128, sum123, MASK, b, a]
    add                   // [result, MASK, b, a]

    // Clean stack
    swap3 pop pop pop     // [result]
}

/// @notice Divide two unsigned 127.128 fixed-point numbers (full precision)
/// @dev takes(2) returns(1)
/// Stack input: [b, a] (b on top, both must be positive/unsigned)
/// Stack output: [a * 2^128 / b]
/// Formula: result = (a * 2^128) / b using Remco Bloemen mulDiv algorithm
/// Gas: ~450-550 (mulmod + modular inverse via Newton-Raphson)
/// Precision: Full 128 fractional bits (exact for all inputs)
#define fn FP127_DIV_UNSIGNED() = takes(2) returns(1) {
    // Input: [b, a]
    // We want to compute (a * 2^128) / b
    // Using Remco Bloemen's mulDiv algorithm from Uniswap V3

    // Step 1: Compute 512-bit product [prod1:prod0] = a * 2^128
    // For multiplier = 2^128, this simplifies to:
    // prod0 = a << 128
    // prod1 = a >> 128
    dup2 0x80 shl              // [prod0, b, a]
    dup3 0x80 shr              // [prod1, prod0, b, a]

    // Step 2: Make division exact by subtracting remainder
    // remainder = mulmod(a, 2^128, b)
    // mulmod pops [a, b, N] and pushes (a * b) % N
    // We need [a, 2^128, b] on top so it computes (a * 2^128) % b
    dup3 [ONE_FP127] dup6      // [a, 2^128, b, prod1, prod0, b, a]
    mulmod                     // [remainder, prod1, prod0, b, a]

    // Subtract remainder from [prod1:prod0]
    // Solidity: prod1 := sub(prod1, gt(remainder, prod0))
    //           prod0 := sub(prod0, remainder)
    dup3 dup2 gt               // [remainder>prod0, remainder, prod1, prod0, b, a]
    dup3 sub                   // [prod1-borrow, remainder, prod1, prod0, b, a]
    swap2 pop                  // [remainder, prod1_new, prod0, b, a]
    dup3 sub                   // [prod0-remainder, prod1_new, prod0, b, a]
    swap2 pop                  // [prod1_new, prod0_new, b, a]
    swap1                      // [prod0, prod1, b, a]

    // Step 3: Factor powers of two out of denominator
    // twos = -b & b (largest power of 2 dividing b)
    dup3 dup1 0x00 sub and     // [twos, prod0, prod1, b, a]

    // Divide b by twos
    dup1 dup5 div              // [b/twos, twos, prod0, prod1, b, a]
    swap4 pop                  // [twos, prod0, prod1, b_new, a]

    // Divide prod0 by twos
    dup1 dup3 div              // [prod0/twos, twos, prod0, prod1, b, a]
    swap2 pop                  // [twos, prod0_new, prod1, b, a]

    // Shift in bits from prod1 into prod0
    // Solidity: twos := add(div(sub(0, twos), twos), 1)
    //           prod0 |= prod1 * twos  (where twos is now the new value)
    // Stack: [twos, prod0, prod1, b, a]
    dup1 0x00 sub              // [-twos, twos, prod0, prod1, b, a]
    div                        // [(-twos)/twos, prod0, prod1, b, a]
    0x01 add                   // [twos_flipped, prod0, prod1, b, a]
    dup3 mul                   // [prod1*twos_flipped, prod0, prod1, b, a]
    dup2 or                    // [prod0_final, prod0, prod1, b, a]
    swap1 pop swap1 pop        // [prod0_final, b, a]

    // Step 4: Compute modular inverse of b mod 2^256
    // inv = (3 * b) ^ 2
    dup2 0x03 mul 0x02 xor     // [inv, prod0, b, a]

    // Newton-Raphson: inv *= 2 - b * inv (6 iterations for 256-bit precision)
    dup3 dup2 mul 0x02 sub mul
    dup3 dup2 mul 0x02 sub mul
    dup3 dup2 mul 0x02 sub mul
    dup3 dup2 mul 0x02 sub mul
    dup3 dup2 mul 0x02 sub mul
    dup3 dup2 mul 0x02 sub mul

    // Step 5: result = prod0 * inv
    swap1 mul swap2 pop pop    // [result]
}

/// @notice Divide two signed 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input: [b, a] (b on top)
/// Stack output: [a / b]
/// Formula: result = (a * 2^128) / b (signed)
/// Gas: ~500-600 (sign handling + unsigned div)
/// Precision: Full 128 fractional bits
/// @dev Converted to function to save ~228 bytes (4 call sites)
#define fn FP127_DIV() = takes(2) returns(1) {
    // Input: [b, a]
    // Strategy: compute sign, abs both, unsigned div, conditionally negate

    // result_sign = (a sar 255) ^ (b sar 255)
    // 0 = same sign (positive result), nonzero = different signs (negative result)
    dup2 0xff sar              // [a_sign, b, a]
    dup2 0xff sar              // [b_sign, a_sign, b, a]
    xor                        // [result_sign, b, a]

    // abs(b): mask = b sar 255; abs = (b ^ mask) - mask
    dup2                       // [b, result_sign, b, a]
    dup1 0xff sar              // [mask, b, result_sign, b, a]
    dup1 dup3 xor              // [b^mask, mask, b, result_sign, b, a]
    sub                        // [abs_b, b, result_sign, b, a]
    swap1 pop                  // [abs_b, result_sign, b, a]

    // abs(a): mask = a sar 255; abs = (a ^ mask) - mask
    dup4                       // [a, abs_b, result_sign, b, a]
    dup1 0xff sar              // [mask, a, abs_b, result_sign, b, a]
    dup1 dup3 xor              // [a^mask, mask, a, abs_b, result_sign, b, a]
    sub                        // [abs_a, a, abs_b, result_sign, b, a]
    swap1 pop                  // [abs_a, abs_b, result_sign, b, a]

    // FP127_DIV_UNSIGNED expects [b, a] (b on top)
    swap1                      // [abs_b, abs_a, result_sign, b, a]
    FP127_DIV_UNSIGNED()       // [result, result_sign, b, a]

    // Apply sign: result = (result ^ sign_mask) - sign_mask
    // This negates if sign_mask is all-ones, identity if zero
    swap1                      // [result_sign, result, b, a]
    dup1 dup3 xor              // [result^sign, result_sign, result, b, a]
    sub                        // [(result^sign)-sign, result, b, a]
    swap1 pop                  // [signed_result, b, a]
    swap2 pop pop              // [signed_result]
}

/// @title FP127 Binary Logarithm (base 2)
/// @notice log2(x) for 127.128 fixed-point arithmetic
/// @dev Requires: primitives.huff and arithmetic.huff must be included before this file
///
/// Algorithm:
///   1. Find MSB, extract integer part: floor(log2(x)) = msb - 128
///   2. Normalize x into [1, 2) by shifting
///   3. Range-reduce m through 7 stages using precomputed 2^(1/2^k) thresholds:
///      For each k=1..7: if m >= 2^(1/2^k), multiply m by 2^(-1/2^k) and add 2^(-k) to result
///      After 7 stages, m is in [1, 2^(1/128)) so f = m-1 is in [0, ~0.0054)
///   4. Evaluate h(f) = ln(1+f)/f via degree-17 Horner polynomial
///   5. Compute log2(m_reduced) = f * (1/ln2) * h(f)
///   6. Result = integer_part + range_reduction_bits + polynomial_part
///
/// Gas: ~3,500
/// Precision: ~126 fractional bits

// ============================================================================
// Sub-macros for FP127_LOG2
// ============================================================================

/// @notice Normalize x into [1, 2) given msb
/// @dev takes(2) returns(1)
/// Stack input:  [msb, x]
/// Stack output: [m] where m is in [ONE_FP127, TWO_FP127)
#define macro FP127_LOG2_NORMALIZE() = takes(2) returns(1) {
    // Stack: [msb, x]
    [FP127_SHIFT] swap1 sub    // [msb - 128, x]

    dup1 IS_NEGATIVE() normalize_shift_left jumpi

    // msb >= 128: shift right
    shr                        // [m = x >> shift]
    normalize_done jump

    normalize_shift_left:
    // msb < 128: shift left
    NEGATE()                   // [128 - msb, x]
    shl                        // [m = x << shift]

    normalize_done:
}

/// @notice Range-reduce m from [1,2) to [1, 2^(1/128)) via 7 squaring stages
/// @dev takes(1) returns(2)
/// Stack input:  [m] where m is in [ONE_FP127, TWO_FP127)
/// Stack output: [m_reduced, frac_accum] where m_reduced is in [ONE_FP127, ~1.0054) and frac_accum accumulates the 7 fractional bits
#define macro FP127_LOG2_RANGE_REDUCE() = takes(1) returns(2) {
    // Stack: [m], need [m, frac_accum]
    0x00                       // [frac_accum=0, m]
    swap1                      // [m, frac_accum]

    // Stage 1: threshold = sqrt(2), frac = 1/2
    dup1 [SQRT2_FP127] gt log2_rs1_skip jumpi
    [LOG2_INV_RT1] FP127_MUL()
    swap1 0x80000000000000000000000000000000 add swap1
    log2_rs1_skip:

    // Stage 2: threshold = 2^(1/4), frac = 1/4
    dup1 [LOG2_RT2] gt log2_rs2_skip jumpi
    [LOG2_INV_RT2] FP127_MUL()
    swap1 0x40000000000000000000000000000000 add swap1
    log2_rs2_skip:

    // Stage 3: threshold = 2^(1/8), frac = 1/8
    dup1 [LOG2_RT3] gt log2_rs3_skip jumpi
    [LOG2_INV_RT3] FP127_MUL()
    swap1 0x20000000000000000000000000000000 add swap1
    log2_rs3_skip:

    // Stage 4: threshold = 2^(1/16), frac = 1/16
    dup1 [LOG2_RT4] gt log2_rs4_skip jumpi
    [LOG2_INV_RT4] FP127_MUL()
    swap1 0x10000000000000000000000000000000 add swap1
    log2_rs4_skip:

    // Stage 5: threshold = 2^(1/32), frac = 1/32
    dup1 [LOG2_RT5] gt log2_rs5_skip jumpi
    [LOG2_INV_RT5] FP127_MUL()
    swap1 0x08000000000000000000000000000000 add swap1
    log2_rs5_skip:

    // Stage 6: threshold = 2^(1/64), frac = 1/64
    dup1 [LOG2_RT6] gt log2_rs6_skip jumpi
    [LOG2_INV_RT6] FP127_MUL()
    swap1 0x04000000000000000000000000000000 add swap1
    log2_rs6_skip:

    // Stage 7: threshold = 2^(1/128), frac = 1/128
    dup1 [LOG2_RT7] gt log2_rs7_skip jumpi
    [LOG2_INV_RT7] FP127_MUL()
    swap1 0x02000000000000000000000000000000 add swap1
    log2_rs7_skip:

    // Stack: [m_reduced, frac_accum]
}

/// @notice Evaluate minimax polynomial for log2(1+f) directly
/// @dev takes(1) returns(1)
/// Stack input:  [f] where f is in [0, ~0.0054)
/// Stack output: [log2(1+f)] computed via degree-13 minimax polynomial
/// @dev Converted to function to save ~194 bytes (2 call sites would be 1 internal)
#define fn FP127_LOG2_POLY() = takes(1) returns(1) {
    // Stack: [f]
    // Evaluate P(f) = log2(1+f) directly via Horner
    // P(f) = P13*f^13 + ... + P1*f + P0
    // Horner: (((...((P13*f + P12)*f + P11)*f + ...)*f + P1)*f + P0

    [LOG2_P13]                 // [P13, f]

    // 12 Horner steps: result = result * f + P_n
    dup2 FP127_MUL() [LOG2_P12] add
    dup2 FP127_MUL() [LOG2_P11] add
    dup2 FP127_MUL() [LOG2_P10] add
    dup2 FP127_MUL() [LOG2_P9] add
    dup2 FP127_MUL() [LOG2_P8] add
    dup2 FP127_MUL() [LOG2_P7] add
    dup2 FP127_MUL() [LOG2_P6] add
    dup2 FP127_MUL() [LOG2_P5] add
    dup2 FP127_MUL() [LOG2_P4] add
    dup2 FP127_MUL() [LOG2_P3] add
    dup2 FP127_MUL() [LOG2_P2] add
    dup2 FP127_MUL() [LOG2_P1] add

    // Final step: result = result * f + P0 (consumes f via swap1)
    swap1 FP127_MUL() [LOG2_P0] add
    // Stack: [log2(1+f)]
}

// ============================================================================
// Full FP127_LOG2
// ============================================================================

/// @notice Compute log2(x) using CLZ + range reduction + polynomial
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, must be > 0)
/// Stack output: [log2(x)] (127.128 format, signed)
#define fn FP127_LOG2() = takes(1) returns(1) {
    dup1 iszero log2_zero jumpi
    dup1 IS_NEGATIVE() log2_zero jumpi
    dup1 [ONE_FP127] eq log2_one jumpi

    // Find MSB
    dup1                       // [x, x]
    MSB()                      // [msb, x]

    // Compute integer part: (msb - 128) << 128, store to memory
    dup1                       // [msb, msb, x]
    [FP127_SHIFT] swap1 sub    // [msb - 128, msb, x]
    [FP127_SHIFT] shl          // [int_part, msb, x]
    0x00 mstore                // [msb, x]

    // Normalize x into [1,2)
    FP127_LOG2_NORMALIZE()     // [m]

    // Range-reduce m to [1, 2^(1/128))
    FP127_LOG2_RANGE_REDUCE()  // [m_reduced, frac_accum]

    // Compute f = m_reduced - 1
    [ONE_FP127] swap1 sub      // [f, frac_accum]

    // Evaluate polynomial
    FP127_LOG2_POLY()          // [poly_result, frac_accum]

    // Total fractional part = frac_accum + poly_result
    add                        // [total_frac]

    // Add integer part from memory
    0x00 mload                 // [int_part, total_frac]
    add                        // [result]

    log2_end jump

    log2_one:
    pop 0x00
    log2_end jump

    log2_zero:
    pop 0x00

    log2_end:
}

/// @title FP127 Exponential Functions
/// @notice 2^x and e^x for 127.128 fixed-point arithmetic
/// @dev Requires: arithmetic.huff and constants.huff must be included before this file
///
/// Algorithm for 2^x:
///   1. Split x into integer k and fractional frac parts
///   2. Compute 2^frac using degree-22 minimax polynomial (Horner evaluation)
///   3. Scale by 2^k (bit shift)
///   4. For negative x: compute 2^(-|x|) directly
///
/// Gas: ~2,500 for 22 Horner steps
/// Precision: ~131 bits (max error < 2^-131)

// ============================================================================
// Horner Step Function for Polynomial Evaluation
// ============================================================================

/// @notice Single Horner step: result = result * x + coeff
/// @dev Stack: [coeff, result, x] -> [result * x + coeff, x]
/// @dev Converted to function to save ~234 bytes (22 call sites)
#define fn HORNER_STEP() = takes(3) returns(2) {
    // Input: [coeff, result, x]
    swap1              // [result, coeff, x]
    dup3               // [x, result, coeff, x]
    FP127_MUL()        // [result*x, coeff, x]
    add                // [result*x+coeff, x]
}

// ============================================================================
// EXP2_FRAC: Compute 2^frac for frac in [0, 1) using minimax polynomial
// ============================================================================

/// @notice Compute 2^frac where frac is the fractional part (128 bits)
/// @dev takes(1) returns(1)
/// Stack input:  [frac] (lower 128 bits of the base-2 exponent, in FP127 format)
/// Stack output: [2^frac] (127.128 format)
/// Algorithm: Horner evaluation of degree-22 minimax polynomial
///   P(f) = C22*f^22 + C21*f^21 + ... + C1*f + C0
///   Horner: (((...((C22*f + C21)*f + C20)*f + ...)*f + C1)*f + C0
#define macro EXP2_FRAC() = takes(1) returns(1) {
    // Input: [frac]
    // Start with highest coefficient C22
    [EXP2_C22]                // [result = C22, frac]

    // 21 Horner steps using the HORNER_STEP function
    [EXP2_C21] HORNER_STEP()
    [EXP2_C20] HORNER_STEP()
    [EXP2_C19] HORNER_STEP()
    [EXP2_C18] HORNER_STEP()
    [EXP2_C17] HORNER_STEP()
    [EXP2_C16] HORNER_STEP()
    [EXP2_C15] HORNER_STEP()
    [EXP2_C14] HORNER_STEP()
    [EXP2_C13] HORNER_STEP()
    [EXP2_C12] HORNER_STEP()
    [EXP2_C11] HORNER_STEP()
    [EXP2_C10] HORNER_STEP()
    [EXP2_C9] HORNER_STEP()
    [EXP2_C8] HORNER_STEP()
    [EXP2_C7] HORNER_STEP()
    [EXP2_C6] HORNER_STEP()
    [EXP2_C5] HORNER_STEP()
    [EXP2_C4] HORNER_STEP()
    [EXP2_C3] HORNER_STEP()
    [EXP2_C2] HORNER_STEP()
    [EXP2_C1] HORNER_STEP()

    // Final Horner step: result = result * frac + C0 (consume frac)
    swap1 FP127_MUL() [EXP2_C0] add

    // Stack: [2^frac]
}

// ============================================================================
// FP127_EXP2_CORE: Core 2^x logic without bounds checking
// ============================================================================

/// @notice Core 2^x computation (no guards - caller must validate input)
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, signed, must be in [-128, 127])
/// Stack output: [2^x] (127.128 format)
#define fn FP127_EXP2_CORE() = takes(1) returns(1) {
    // Check for zero
    dup1 iszero exp2c_zero jumpi

    dup1 IS_NEGATIVE() exp2c_negative jumpi

    // Positive x: split into integer and fractional parts
    dup1 [FP127_SHIFT] sar     // [k_int, x]
    swap1 [MASK128] and        // [frac, k_int]
    EXP2_FRAC()                // [2^frac, k_int]
    swap1 shl                  // [result]
    exp2c_done jump

    exp2c_negative:
    NEGATE()                   // [|x|]
    dup1 [FP127_SHIFT] shr     // [|k_int|, |x|]
    swap1 [MASK128] and        // [frac_of_neg, |k_int|]

    dup1 iszero exp2c_neg_no_frac jumpi

    [ONE_FP127] sub            // [1-frac, |k_int|]
    EXP2_FRAC()                // [2^(1-frac), |k_int|]
    swap1 0x01 add             // [|k_int|+1, 2^(1-frac)]
    shr                        // [result]
    exp2c_done jump

    exp2c_neg_no_frac:
    pop                        // [|k_int|]
    [ONE_FP127] swap1 shr      // [result]
    exp2c_done jump

    exp2c_zero:
    pop
    [ONE_FP127]

    exp2c_done:
}

// ============================================================================
// FP127_EXP2: Compute 2^x with bounds checking
// ============================================================================

/// @notice Compute 2^x using minimax polynomial (guarded entry point)
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, signed)
/// Stack output: [2^x] (127.128 format)
#define fn FP127_EXP2() = takes(1) returns(1) {
    [EXP2_OVERFLOW_THRESHOLD] dup2 sgt exp2_overflow jumpi
    [EXP2_UNDERFLOW_THRESHOLD] dup2 slt exp2_underflow jumpi

    FP127_EXP2_CORE()
    exp2_done jump

    exp2_overflow:
    pop
    [MAX_UINT256]
    exp2_done jump

    exp2_underflow:
    pop
    0x00

    exp2_done:
}

// ============================================================================
// FP127_EXP: Compute e^x for 127.128 fixed-point x
// ============================================================================

/// @notice Compute e^x using exp2(x * 1/ln(2))
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, signed)
/// Stack output: [exp(x)] (127.128 format)
///
/// Gas: ~2,700
/// Precision: ~131 bits
#define fn FP127_EXP() = takes(1) returns(1) {
    dup1 iszero exp_zero jumpi

    [EXP_OVERFLOW_THRESHOLD] dup2 sgt    // [x > 88, x]
    exp_overflow jumpi
    [EXP_UNDERFLOW_THRESHOLD] dup2 slt   // [x < -88, x]
    exp_underflow jumpi

    // exp(x) = 2^(x * log2(e))
    [INV_LN2_FP127]            // [INV_LN2, x]
    FP127_MUL()                // [x * INV_LN2]

    // After EXP bounds check, x*INV_LN2 is guaranteed within EXP2 range
    FP127_EXP2_CORE()          // [exp(x)]
    exp_done jump

    exp_overflow:
    pop
    [MAX_UINT256]
    exp_done jump

    exp_underflow:
    pop
    0x00
    exp_done jump

    exp_zero:
    pop
    [ONE_FP127]

    exp_done:
}

/// @title FP127 Natural Logarithm
/// @notice ln(x) for 127.128 fixed-point arithmetic using log2-based algorithm
/// @dev Requires: log2.huff and arithmetic.huff must be included before this file
///
/// Algorithm:
///   ln(x) = log2(x) * ln(2)
///
/// Gas: ~3,800 (log2 ~3,500 + MUL ~130 + overhead)
/// Precision: ~126 fractional bits

/// @notice Compute ln(x) using log2(x) * ln(2)
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, must be > 0)
/// Stack output: [ln(x)] (127.128 format, signed)
/// Note: Guards (zero, negative, x==1) are handled inside FP127_LOG2
#define fn FP127_LN() = takes(1) returns(1) {
    FP127_LOG2()               // [log2(x)]

    // log2 returns 0 for x==1, x==0, x<0 -- check if we got 0
    dup1 iszero ln_zero jumpi

    [LN2_FP127]                // [LN2, log2(x)]
    FP127_MUL()                // [ln(x)]
    ln_done jump

    ln_zero:

    ln_done:
}

/// @title FP127 Square Root
/// @notice Carmack CLZ initial guess + Newton-Raphson refinement
/// @dev 127.128 fixed-point format
/// @dev Requires: arithmetic.huff (FP127_DIV_UNSIGNED) must be included before this file

/// @notice Compute sqrt(x) using Carmack initial guess + Newton-Raphson
/// @dev takes(1) returns(1)
/// Stack input:  [x] (127.128 format, must be >= 0)
/// Stack output: [sqrt(x)] (127.128 format)
///
/// Algorithm:
///   1. Binary search to find MSB
///   2. Carmack guess: y_0 = 2^((128 + msb) / 2)
///   3. 7 Newton iterations: y = (y + x/y) / 2
///
/// Gas: ~1600
/// Precision: ~38 decimal digits (128 fractional bits)
#define fn FP127_SQRT() = takes(1) returns(1) {
    // Input: [x]
    dup1 iszero sqrt_is_zero jumpi

    // Find MSB using primitives.huff macro
    dup1                                // [x, x]
    MSB()                               // [msb, x]

    // Improved Carmack initial guess:
    // y_0 = 2^(floor((128 + msb) / 2))
    // If (128 + msb) is odd, multiply by sqrt(2) to halve initial error
    [FP127_SHIFT] add                   // [128 + msb, x]
    dup1 0x01 and                       // [parity, 128+msb, x]
    swap1 0x01 shr                      // [half_exp, parity, x]
    0x01 swap1 shl                      // [y_0 = 2^half_exp, parity, x]

    // If parity is 1, multiply by SQRT2_FP127
    swap1 iszero sqrt_no_sqrt2 jumpi
    [SQRT2_FP127]                       // [SQRT2, y_0, x]
    FP127_MUL()                         // [y_0 * sqrt2, x]
    sqrt_no_sqrt2:
    // Stack: [y_0, x]

    // 7 Newton iterations: y = (y + x/y) / 2
    NEWTON_SQRT_STEP()                  // [y_1, x]
    NEWTON_SQRT_STEP()                  // [y_2, x]
    NEWTON_SQRT_STEP()                  // [y_3, x]
    NEWTON_SQRT_STEP()                  // [y_4, x]
    NEWTON_SQRT_STEP()                  // [y_5, x]
    NEWTON_SQRT_STEP()                  // [y_6, x]
    NEWTON_SQRT_STEP()                  // [y_7, x]

    // Return result
    swap1 pop                           // [y_7]
    sqrt_done jump

    sqrt_is_zero:
    // x is 0, already on stack
    sqrt_done:
}

/// @title FP127 Power Function
/// @notice x^y for 127.128 fixed-point arithmetic
/// @dev Requires: log2.huff, exp.huff, and arithmetic.huff must be included before this file
///
/// Algorithm:
///   x^y = 2^(y * log2(x))
///
/// Edge cases:
///   - y == 0: return 1 (x^0 = 1 for all x, including 0^0 = 1 by convention)
///   - x == 0: return 0 (0^y = 0 for y != 0)
///   - x == 1: return 1 (1^y = 1 for all y)
///   - x < 0: revert (fractional powers of negatives are undefined in reals)
///
/// Gas: ~6,500 (log2 ~3,500 + mul ~130 + exp2 ~2,500 + overhead)
/// Precision: ~126 fractional bits (compounded from log2 and exp2 precision)

/// @notice Compute x^y using log2 and exp2
/// @dev takes(2) returns(1)
/// Stack input:  [y, x] (both 127.128 format, signed)
/// Stack output: [x^y] (127.128 format)
#define macro FP127_POW() = takes(2) returns(1) {
    // Stack: [y, x]

    // Check if y == 0 (any x^0 = 1)
    dup1 iszero pow_y_zero jumpi

    // Check if x == 0 (0^y = 0 for y != 0)
    dup2 iszero pow_x_zero jumpi

    // Check if x == 1 (1^y = 1 for all y)
    dup2 [ONE_FP127] eq pow_x_one jumpi

    // Check if x < 0 (revert for negative base)
    dup2 IS_NEGATIVE() pow_x_negative jumpi

    // Main path: x^y = 2^(y * log2(x))
    swap1                      // [x, y]
    FP127_LOG2()               // [log2(x), y]
    FP127_MUL()                // [y * log2(x)]
    FP127_EXP2()               // [2^(y * log2(x)) = x^y]
    pow_done jump

    pow_y_zero:
    // y == 0: return 1
    pop pop                    // Clear stack
    [ONE_FP127]                // [1.0]
    pow_done jump

    pow_x_zero:
    // x == 0: return 0
    pop pop                    // Clear stack
    0x00                       // [0]
    pow_done jump

    pow_x_one:
    // x == 1: return 1
    pop pop                    // Clear stack
    [ONE_FP127]                // [1.0]
    pow_done jump

    pow_x_negative:
    // x < 0: revert (fractional powers of negatives are undefined)
    0x00 0x00 revert

    pow_done:
}

/// @title FP127 Utility Functions
/// @notice Utility operations for 127.128 fixed-point arithmetic
/// @dev Simple operations like abs, min, max, avg, etc.
/// @dev Requires: constants.huff and primitives.huff must be included before this file

// ============================================================================
// Sign and Negation Utilities
// ============================================================================

/// @notice Absolute value of a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [|x|]
/// Formula: abs(x) = x < 0 ? -x : x
/// Gas: ~8 opcodes
#define macro FP127_ABS() = takes(1) returns(1) {
    // mask = x >> 255 (all 1s if negative, all 0s if positive)
    // abs = (x ^ mask) - mask
    dup1 0xff sar              // [mask, x]
    dup1 dup3 xor              // [x^mask, mask, x]
    sub                        // [abs_x, x]
    swap1 pop                  // [abs_x]
}

/// @notice Negate a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [-x]
/// Gas: ~3 opcodes
#define macro FP127_NEG() = takes(1) returns(1) {
    NEGATE()
}

/// @notice Reciprocal of a 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [1/x]
/// Formula: 1/x = ONE / x
/// Gas: ~500-600 (calls FP127_DIV)
#define macro FP127_INV() = takes(1) returns(1) {
    [ONE_FP127]                // [1, x]
    swap1                      // [x, 1]
    FP127_DIV()                // [1/x]
}

// ============================================================================
// Comparison and Selection
// ============================================================================

/// @notice Minimum of two signed 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input:  [b, a] (b on top)
/// Stack output: [min(a, b)]
/// Gas: ~10 opcodes
#define macro FP127_MIN() = takes(2) returns(1) {
    // Stack: [b, a]
    dup2 dup2                  // [b, a, b, a]
    slt                        // [a < b, b, a]
    min_select jumpi           // [b, a]
    pop                        // [a] - b is min
    min_done jump
    min_select:
    swap1 pop                  // [b] - a is min
    min_done:
}

/// @notice Maximum of two signed 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input:  [b, a] (b on top)
/// Stack output: [max(a, b)]
/// Gas: ~10 opcodes
#define macro FP127_MAX() = takes(2) returns(1) {
    // Stack: [b, a]
    dup2 dup2                  // [b, a, b, a]
    sgt                        // [a > b, b, a]
    max_select jumpi           // [b, a]
    pop                        // [a] - b is max
    max_done jump
    max_select:
    swap1 pop                  // [b] - a is max
    max_done:
}

/// @notice Clamp a value to a range [lo, hi]
/// @dev takes(3) returns(1)
/// Stack input:  [hi, lo, x] (hi on top)
/// Stack output: [clamped_x]
/// Formula: clamp(x, lo, hi) = max(lo, min(x, hi))
/// Gas: ~20 opcodes
#define macro FP127_CLAMP() = takes(3) returns(1) {
    // Stack: [hi, lo, x]
    swap2                      // [x, lo, hi]
    swap1                      // [lo, x, hi]
    FP127_MAX()                // [max(lo, x), hi]
    swap1                      // [hi, max(lo, x)]
    FP127_MIN()                // [min(hi, max(lo, x))]
}

// ============================================================================
// Arithmetic Utilities
// ============================================================================

/// @notice Overflow-safe average of two signed 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input:  [b, a] (b on top)
/// Stack output: [(a + b) / 2]
/// Formula: avg = (a >> 1) + (b >> 1) + (a & b & 1)
/// This avoids overflow that would occur with (a + b) / 2
/// Gas: ~10 opcodes
#define macro FP127_AVG() = takes(2) returns(1) {
    // Stack: [b, a]
    dup2 0x01 sar              // [a>>1, b, a]
    dup2 0x01 sar              // [b>>1, a>>1, b, a]
    add                        // [sum, b, a]
    swap2 and 0x01 and         // [a&b&1, sum]
    add                        // [avg]
}

/// @notice Saturating subtraction: max(0, a - b)
/// @dev takes(2) returns(1)
/// Stack input:  [b, a] (b on top)
/// Stack output: [max(0, a - b)]
/// Gas: ~15 opcodes
#define macro FP127_ZERO_FLOOR_SUB() = takes(2) returns(1) {
    // Stack: [b, a]
    FP127_SUB()                // [a - b]
    dup1 IS_NEGATIVE()         // [is_neg, a-b]
    zfs_select jumpi           // [a-b]
    zfs_done jump
    zfs_select:
    pop 0x00                   // [0]
    zfs_done:
}

/// @notice Distance between two signed 127.128 fixed-point numbers
/// @dev takes(2) returns(1)
/// Stack input:  [b, a] (b on top)
/// Stack output: [|a - b|]
/// Formula: dist(a, b) = abs(a - b)
/// Gas: ~15 opcodes
#define macro FP127_DIST() = takes(2) returns(1) {
    // Stack: [b, a]
    FP127_SUB()                // [a - b]
    FP127_ABS()                // [|a - b|]
}

