// Rounding and Sign Functions
// ============================================================================

/// @notice Sign of a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [-1 if x < 0, 0 if x == 0, +1 if x > 0] (in FP127 format)
/// Formula: sign(x) = (x > 0) - (x < 0), scaled to FP127
/// Gas: ~10 opcodes
#define macro FP127_SIGN() = takes(1) returns(1) {
    // Stack: [x]
    dup1 0x00 sgt              // [x > 0, x]
    swap1 0x00 slt             // [x < 0, x > 0]
    sub                        // [(x > 0) - (x < 0)]
    [FP127_SHIFT] shl          // [sign << 128] = sign in FP127
}

/// @notice Floor of a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [floor(x)] (largest integer <= x, in FP127 format)
/// Formula: Mask off fractional bits, adjust for negative non-integers
/// Gas: ~15 opcodes
/// @dev Converted to function to save bytecode (called by ceil, frac)
#define fn FP127_FLOOR() = takes(1) returns(1) {
    // In two's complement, AND with INT_MASK (zeroing fractional bits)
    // always rounds toward -infinity, which IS floor for both positive and negative.
    [INT_MASK] and
}

/// @notice Ceiling of a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [ceil(x)] (smallest integer >= x, in FP127 format)
/// Formula: ceil(x) = -floor(-x)
/// Gas: ~20 opcodes
#define macro FP127_CEIL() = takes(1) returns(1) {
    // Stack: [x]
    NEGATE()                   // [-x]
    FP127_FLOOR()              // [floor(-x)]
    NEGATE()                   // [-floor(-x) = ceil(x)]
}

/// @notice Fractional part of a signed 127.128 fixed-point number
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [frac(x)] (x - floor(x), always non-negative)
/// Formula: frac(x) = x - floor(x)
/// Gas: ~20 opcodes
#define macro FP127_FRAC() = takes(1) returns(1) {
    // frac(x) = x & FRAC_MASK (lower 128 bits are the fractional part)
    [FRAC_MASK] and
}

/// @notice Round to nearest integer (round half up)
/// @dev takes(1) returns(1)
/// Stack input:  [x]
/// Stack output: [round(x)] (nearest integer to x, in FP127 format)
/// Formula: round(x) = floor(x + 0.5)
/// Gas: ~20 opcodes
#define macro FP127_ROUND() = takes(1) returns(1) {
    // Stack: [x]
    [HALF_FP127] add           // [x + 0.5]
    FP127_FLOOR()              // [floor(x + 0.5)]
}

